{
  "technical_and_design_decisions": [
    "For U6, opt for a separate API function for system channel genesis (rather than a combined function with application channel creation) to keep responsibilities clear and align with the modern configtx API style.",
    "For U8, extend the SigningIdentity interface with both SignConfigUpdate and the renamed SignConfigUpdateEnvelope, encapsulating all config-signing operations behind the identity abstraction.",
    "For U3, new policy functions for the channel group will mirror the existing pattern used for the application/orderer groups, parameterized by the channel group key.",
    "For U4, expose three distinct exported functions (one per group) rather than a single function with a group-type parameter, to keep the API explicit and self-documenting.",
    "Example tests are consolidated within the existing example_test.go file in the configtx package; a new dedicated example is added for U6 (system channel genesis).",
    "All new public functions follow Go conventions: return (value, error) where appropriate, use ConfigValue/ConfigPolicy wrapper helpers consistent with the package.",
    "For U8, CreateSignedConfigUpdateEnvelope is renamed in place and any external callers (including the configtxgen CLI) are updated to match the new name.",
    "The Overview section (U7) is placed in a dedicated doc.go file to keep it visible and avoid being overshadowed by the package declaration."
  ],
  "assumptions": [
    "The developer is already familiar with the Hyperledger Fabric codebase, Go, and protobuf-generated config types; no onboarding ramp is required.",
    "The supporting aggregator functions for retrieving dependent config fields (referenced in U1) are already implemented and available to compose into a full channel config.",
    "A single example_test.go file exists in the configtx package; new examples are appended/updated there unless a user story explicitly requires a new example file (U6).",
    "Standard Go testing (testing package) is used for unit tests; no new test frameworks or dependencies are introduced.",
    "The signing identity interface change in U8 is treated as an acceptable API change (Hyperledger Fabric was still evolving the configtx API at the relevant point in history).",
    "Code review and final integration testing are part of the development effort and are accounted for as a dedicated activity.",
    "An 8-hour workday is assumed; estimates are best-case for a single experienced developer without significant interruptions or unknowns.",
    "No documentation beyond GoDoc/GoDocs Overview and example tests is required (e.g., no separate design docs or wiki updates)."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Codebase analysis and development environment setup",
      "activity_description": "Re-familiarize with the configtx package structure, existing config builders, aggregator helpers, and proto types; set up the local build/test environment and confirm baseline tests pass.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A2",
      "activity_name": "U1: Implement full channel configuration retrieval",
      "activity_description": "Add a public function (e.g., GetChannelConfig) that composes the existing aggregator helpers to return the entire config.Channel for a given channel config, without manual config transaction parsing.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A3",
      "activity_name": "U1: Unit tests for full channel config retrieval",
      "activity_description": "Write unit tests covering happy-path and a couple of edge cases (e.g., minimal config, config with multiple orgs); update example_test.go to demonstrate usage.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A4",
      "activity_name": "U2: Implement update of consortium channel creation policy",
      "activity_description": "Add a function that updates the channel creation policy ConfigValue in the consortium group of an existing config.Channel; follow existing ConfigValue mutator conventions.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A5",
      "activity_name": "U2: Unit tests and example test for U2",
      "activity_description": "Add unit tests for the new updater (set, replace, error paths) and add an example demonstrating updating the channel creation policy in example_test.go.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A6",
      "activity_name": "U3: Implement channel group policy operations (add/remove/retrieve)",
      "activity_description": "Add three public functions: add a policy to the channel group, remove a policy from the channel group, and retrieve the existing channel group policies. Mirror the patterns used for other groups but adapt to the channel group structure.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A7",
      "activity_name": "U3: Unit tests and example test updates for channel group policies",
      "activity_description": "Write unit tests covering add, remove, retrieve, and not-found/conflict cases; extend example_test.go to demonstrate channel group policy usage.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A8",
      "activity_name": "U4: Implement remove-org functions for consortium, application, and orderer",
      "activity_description": "Add three exported functions: RemoveOrgFromConsortium, RemoveOrgFromApplication, and RemoveOrgFromOrderer. Each removes the org from the corresponding group's Organizations config group by key.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A9",
      "activity_name": "U4: Unit tests and example test updates for org removal",
      "activity_description": "Add unit tests for each of the three remove-org functions (success, missing org, nil config error) and update example_test.go to show usage of each.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A10",
      "activity_name": "U5: Implement remove-consortium function",
      "activity_description": "Add a function that removes a specific consortium, identified by name, from the channel config's Consortiums group.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A11",
      "activity_name": "U5: Unit tests and example test updates for consortium removal",
      "activity_description": "Add unit tests for the remove-consortium function and add an example demonstrating its usage in example_test.go.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A12",
      "activity_name": "U6: Implement system channel genesis block creation",
      "activity_description": "Add a new public function (e.g., NewSystemChannelGenesisBlock) that builds a genesis block with only the channel config group populated with the orderer and consortiums groups (no application group), taking the orderer genesis profile and consortiums from a template.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "A13",
      "activity_name": "U6: Unit tests and new example test for system channel genesis",
      "activity_description": "Write unit tests verifying the absence of an application group and presence of orderer/consortiums groups; add a dedicated example demonstrating system channel genesis block creation.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A14",
      "activity_name": "U7: Write GoDocs Overview section for configtx package",
      "activity_description": "Author a package-level Overview in a new doc.go file that explains the purpose of the configtx package, how channels are structured (channel/application/orderer/consortiums groups), and how to use the public API.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A15",
      "activity_name": "U8: Rename and refactor signing identity API",
      "activity_description": "Rename CreateSignedConfigUpdateEnvelope to SignConfigUpdateEnvelope; extend the SigningIdentity interface to include both SignConfigUpdate and SignConfigUpdateEnvelope; update the default SigningIdentity implementation accordingly.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A16",
      "activity_name": "U8: Update callers, tests, and GoDoc for signing identity changes",
      "activity_description": "Update all internal callers (including the configtxgen CLI) to the new function name and SigningIdentity methods; add unit tests for the new signing methods; write GoDoc comments explaining the difference between SignConfigUpdate and SignConfigUpdateEnvelope.",
      "most_likely_effort": 0.5
    },
    {
      "activity_id": "A17",
      "activity_name": "Final integration testing, code review, and cleanup",
      "activity_description": "Run the full test suite, fix any regressions introduced by renames or new functions, perform a self-review of the diff, ensure all example tests compile and pass, and verify GoDocs render correctly with the new Overview section.",
      "most_likely_effort": 1.5
    }
  ],
  "reported_total": {
    "most_likely_effort": 17.0
  }
}
